    90→    defer tokens.deinit();
    91→
    92→    while (try tokenizer.nextToken()) |token| {
    93→        try tokens.append(token);
    94→    }
    95→
    96→    std.debug.print("✅ Tokenized {} tokens\n\n", .{tokens.items.len});
