   170→
   171→        std.debug.print("✅ Compiled to binary: {s}\n\n", .{binary_filename});
   172→
   173→        // 정리 및 요약
   174→        std.debug.print("========== Compilation Complete (LLVM IR Path) ==========\n", .{});
