   188→    std.debug.print("─────────────────────────\n", .{});
   189→
   190→    var codegen = try Codegen.init(allocator, &sema.air);
   191→    defer codegen.deinit();
   192→
   193→    const c_code = try codegen.generate();
   194→    const c_filename = try std.fmt.allocPrint(allocator, "{s}.c", .{output_file});
   195→    defer allocator.free(c_filename);
   196→
   197→    try codegen.generateToFile(c_filename);
   198→    std.debug.print("✅ Generated C code: {} bytes written to {s}\n\n", .{ c_code.len, c_filename });
   199→
   200→    // --emit-c 플래그가 있으면 여기서 종료
   201→    if (emit_c_only) {
   202→        std.debug.print("[Summary] C code generation complete\n", .{});
   203→        std.debug.print("C file: {s}\n", .{c_filename});
   204→        return;
   205→    }
   206→
   207→    // Step 6: Linker (C → Binary)
   208→    std.debug.print("[Step 6] LINKER (C → Binary)\n", .{});
   209→    std.debug.print("─────────────────────────\n", .{});
   210→
   211→    var linker = try Linker.init(allocator);
   212→    defer linker.deinit();
   213→
   214→    const binary_filename = output_file;
   215→    linker.compile(c_filename, binary_filename) catch |err| {
