     5→/// C 코드를 바이너리로 링크/컴파일하는 래퍼
     6→pub const Linker = struct {
     7→    allocator: std.mem.Allocator,
     8→    cc_path: ?[]const u8,
     9→    llvm_path: ?[]const u8,
    10→
    11→    pub fn init(allocator: std.mem.Allocator) !Linker {
    12→        const cc = findCCompiler(allocator) catch null;
    13→        const llvm = findLLVMCompiler(allocator) catch null;
    14→        return Linker{
    15→            .allocator = allocator,
    16→            .cc_path = cc,
    17→            .llvm_path = llvm,
    18→        };
    19→    }
    20→
    21→    pub fn deinit(self: *Linker) void {
    22→        if (self.cc_path) |cc| {
    23→            self.allocator.free(cc);
    24→        }
    25→        if (self.llvm_path) |llvm| {
    26→            self.allocator.free(llvm);
    27→        }
    28→    }
    29→
    30→    /// C 파일을 바이너리로 컴파일
    31→    /// c_file: 입력 C 파일 경로
    32→    /// output: 출력 바이너리 파일 경로
    33→    pub fn compile(self: *Linker, c_file: []const u8, output: []const u8) !void {
    34→        if (self.cc_path == null) {
    35→            return error.NoCCompilerFound;
    36→        }
    37→
    38→        const cc = self.cc_path.?;
    39→        const argv = [_][]const u8{ cc, c_file, "-o", output };
    40→
    41→        var child = try std.process.Child.init(&argv, self.allocator);
    42→        defer child.deinit();
    43→
    44→        const term = try child.spawnAndWait();
    45→        switch (term) {
    46→            .Exited => |code| {
    47→                if (code != 0) {
    48→                    return error.CompilationFailed;
    49→                }
    50→            },
    51→            else => {
    52→                return error.CompilationTerminatedAbnormally;
    53→            },
    54→        }
    55→    }
    56→
    57→    /// C 파일을 객체 파일로 컴파일 (링킹 전)
    58→    pub fn compileToObject(self: *Linker, c_file: []const u8, output: []const u8) !void {
    59→        if (self.cc_path == null) {
    60→            return error.NoCCompilerFound;
    61→        }
    62→
    63→        const cc = self.cc_path.?;
    64→        const argv = [_][]const u8{ cc, "-c", c_file, "-o", output };
    65→
    66→        var child = try std.process.Child.init(&argv, self.allocator);
    67→        defer child.deinit();
    68→
    69→        const term = try child.spawnAndWait();
    70→        switch (term) {
    71→            .Exited => |code| {
    72→                if (code != 0) {
    73→                    return error.CompilationFailed;
    74→                }
    75→            },
    76→            else => {
    77→                return error.CompilationTerminatedAbnormally;
    78→            },
    79→        }
    80→    }
    81→
    82→    /// 여러 객체 파일을 링크
    83→    pub fn linkObjects(self: *Linker, objects: []const []const u8, output: []const u8) !void {
    84→        if (self.cc_path == null) {
    85→            return error.NoCCompilerFound;
    86→        }
    87→
    88→        const cc = self.cc_path.?;
    89→        var argv = std.ArrayList([]const u8).init(self.allocator);
    90→        defer argv.deinit();
    91→
    92→        try argv.append(cc);
    93→        for (objects) |obj| {
    94→            try argv.append(obj);
    95→        }
    96→        try argv.append("-o");
    97→        try argv.append(output);
    98→
    99→        var child = try std.process.Child.init(argv.items, self.allocator);
   100→        defer child.deinit();
   101→
   102→        const term = try child.spawnAndWait();
   103→        switch (term) {
   104→            .Exited => |code| {
   105→                if (code != 0) {
   106→                    return error.LinkingFailed;
   107→                }
   108→            },
   109→            else => {
   110→                return error.LinkingTerminatedAbnormally;
   111→            },
   112→        }
   113→    }
   114→
   115→    /// 최적화 플래그를 포함하여 컴파일
   116→    pub fn compileWithOptimization(
   117→        self: *Linker,
   118→        c_file: []const u8,
   119→        output: []const u8,
   120→        opt_level: u8,
   121→    ) !void {
   122→        if (self.cc_path == null) {
   123→            return error.NoCCompilerFound;
   124→        }
   125→
   126→        const cc = self.cc_path.?;
   127→        const opt_flag = switch (opt_level) {
   128→            0 => "-O0",
   129→            1 => "-O1",
   130→            2 => "-O2",
   131→            3 => "-O3",
   132→            else => "-O2",
   133→        };
   134→
   135→        const argv = [_][]const u8{ cc, opt_flag, c_file, "-o", output };
   136→
   137→        var child = try std.process.Child.init(&argv, self.allocator);
   138→        defer child.deinit();
   139→
   140→        const term = try child.spawnAndWait();
   141→        switch (term) {
   142→            .Exited => |code| {
   143→                if (code != 0) {
   144→                    return error.CompilationFailed;
   145→                }
   146→            },
   147→            else => {
   148→                return error.CompilationTerminatedAbnormally;
   149→            },
   150→        }
   151→    }
   152→
   153→    /// 디버그 심볼을 포함하여 컴파일
   154→    pub fn compileWithDebugSymbols(self: *Linker, c_file: []const u8, output: []const u8) !void {
   155→        if (self.cc_path == null) {
   156→            return error.NoCCompilerFound;
   157→        }
   158→
   159→        const cc = self.cc_path.?;
   160→        const argv = [_][]const u8{ cc, "-g", c_file, "-o", output };
   161→
   162→        var child = try std.process.Child.init(&argv, self.allocator);
   163→        defer child.deinit();
   164→
   165→        const term = try child.spawnAndWait();
   166→        switch (term) {
   167→            .Exited => |code| {
   168→                if (code != 0) {
   169→                    return error.CompilationFailed;
   170→                }
   171→            },
   172→            else => {
   173→                return error.CompilationTerminatedAbnormally;
   174→            },
   175→        }
   176→    }
   177→
   178→    // ========== LLVM IR 컴파일 메서드 (Phase 6) ==========
   179→
   180→    /// LLVM IR 텍스트를 .ll 파일로 저장
   181→    pub fn writeIRToFile(ir_text: []const u8, path: []const u8) !void {
   182→        const file = try fs.cwd().createFile(path, .{});
   183→        defer file.close();
   184→        try file.writeAll(ir_text);
   185→    }
   186→
   187→    /// .ll 파일을 clang으로 바이너리 컴파일
   188→    /// clang {ll_file} -o {output}
   189→    pub fn compileFromLLVMIR(self: *Linker, ll_file: []const u8, output: []const u8) !void {
   190→        if (self.llvm_path == null) {
   191→            return error.NoLLVMCompilerFound;
   192→        }
   193→
   194→        const llvm = self.llvm_path.?;
   195→        const argv = [_][]const u8{ llvm, ll_file, "-o", output };
   196→
   197→        var child = try std.process.Child.init(&argv, self.allocator);
   198→        defer child.deinit();
   199→
   200→        const term = try child.spawnAndWait();
   201→        switch (term) {
   202→            .Exited => |code| {
   203→                if (code != 0) {
   204→                    return error.CompilationFailed;
   205→                }
   206→            },
   207→            else => {
   208→                return error.CompilationTerminatedAbnormally;
   209→            },
   210→        }
   211→    }
   212→
   213→    /// LLVM IR 텍스트 → 임시 .ll 파일 → 바이너리 (임시파일 자동 삭제)
   214→    pub fn compileIRText(self: *Linker, ir_text: []const u8, output: []const u8) !void {
   215→        const temp_ll = try generateTempFileName(self.allocator, ".ll");
   216→        defer self.allocator.free(temp_ll);
   217→
   218→        try writeIRToFile(ir_text, temp_ll);
   219→        defer {
   220→            deleteFile(temp_ll) catch |err| {
   221→                std.debug.print("⚠️  Warning: Failed to delete temporary file {s}: {}\n", .{ temp_ll, err });
   222→            };
   223→        }
   224→
   225→        try self.compileFromLLVMIR(temp_ll, output);
   226→    }
   227→};
