   229→// ========== 헬퍼 함수 ==========
   230→
   231→/// C 컴파일러 자동 감지 (gcc, clang, cc 순)
   232→fn findCCompiler(allocator: std.mem.Allocator) ![]const u8 {
   233→    const compilers = [_][]const u8{ "gcc", "clang", "cc" };
   234→
   235→    for (compilers) |compiler| {
   236→        const result = try std.process.run(.{
   237→            .allocator = allocator,
   238→            .argv = &[_][]const u8{ compiler, "--version" },
   239→            .capture_stdout = true,
   240→        });
   241→        defer {
   242→            allocator.free(result.stdout);
   243→            allocator.free(result.stderr);
   244→        }
   245→
   246→        if (result.term.Exited == 0) {
   247→            return try allocator.dupe(u8, compiler);
   248→        }
   249→    }
   250→
   251→    return error.NoCCompilerFound;
   252→}
   253→
   254→/// LLVM 컴파일러 자동 감지 (clang, cc 순)
   255→/// clang은 .ll 파일을 직접 바이너리로 컴파일 가능
   256→fn findLLVMCompiler(allocator: std.mem.Allocator) ![]const u8 {
   257→    const compilers = [_][]const u8{ "clang", "cc", "gcc" };
   258→
   259→    for (compilers) |compiler| {
   260→        const result = try std.process.run(.{
   261→            .allocator = allocator,
   262→            .argv = &[_][]const u8{ compiler, "--version" },
   263→            .capture_stdout = true,
   264→        });
   265→        defer {
   266→            allocator.free(result.stdout);
   267→            allocator.free(result.stderr);
   268→        }
   269→
   270→        if (result.term.Exited == 0) {
   271→            return try allocator.dupe(u8, compiler);
   272→        }
   273→    }
   274→
   275→    return error.NoLLVMCompilerFound;
   276→}
