   278→/// 임시 파일명 생성
   279→pub fn generateTempFileName(allocator: std.mem.Allocator, suffix: []const u8) ![]const u8 {
   280→    const timestamp = @as(u64, @bitCast(std.time.nanoTimestamp()));
   281→    return try std.fmt.allocPrint(allocator, "/tmp/zig_tmp_{}{}", .{ timestamp, suffix });
