   203→/// Type 유틸리티 함수들
   204→pub fn typeEq(t1: Type, t2: Type) bool {
   205→    switch (t1) {
   206→        .void => return t2 == .void,
   207→        .i32 => return t2 == .i32,
   208→        .i64 => return t2 == .i64,
   209→        .f32 => return t2 == .f32,
   210→        .f64 => return t2 == .f64,
   211→        .bool => return t2 == .bool,
   212→        .string => return t2 == .string,
   213→        .unknown => return t2 == .unknown,
   214→        .array => |arr1| {
   215→            if (t2 == .array) {
